function lesson(number, slug, title, duration, body) {
  return { type: 'lesson', number, slug, title, duration, ...body };
}

function exercise(slug, title, duration, body) {
  return { type: 'exercise', slug, title, duration, ...body };
}

function resource(slug, title, body) {
  return { type: 'resource', slug, title, ...body };
}

