function buildWorkspaceTourLesson({ number, slug, title, duration, index }) {
  const en = workspaceTourLesson.content.en.elements[index];
  const es = workspaceTourLesson.content.es.elements[index];
  const pt = workspaceTourLesson.content.pt.elements[index];
  const override = workshopLessonOverrides[slug];

  return lesson(number, slug, title, duration, {
    sources: sourceSets.official,
    content: {
      en: {
        summary: slug === 'integrations'
          ? 'Connect external services to extend Seal.'
          : slug === 'mcp-servers'
            ? 'Remote MCP servers available to all your workspaces.'
            : en.description,
        purpose: en.purpose,
        howToUse: en.howToUse,
        benefit: en.benefit,
        prompt: `Explain ${title} in Cloudflare OS: why it exists, how I should use it, and what benefit it gives me.`,
        facilitator: `Open ${title} live and explain only this surface before moving to the next one.`,
        audienceNotes: {
          customer: `Frame ${title} as a concrete operating surface, not just a menu label.`,
          partner: `Frame ${title} as part of a repeatable walkthrough the partner can reuse with customers.`,
        },
        ...override?.en,
      },
      es: {
        summary: slug === 'integrations'
          ? 'Conecta servicios externos para extender Seal.'
          : slug === 'mcp-servers'
            ? 'Servidores MCP remotos disponibles para todos tus workspaces.'
            : es.description,
        purpose: es.purpose,
        howToUse: es.howToUse,
        benefit: es.benefit,
        prompt: `Explicame ${title} en Cloudflare OS: por que existe, como deberia usarlo y que beneficio me da.`,
        facilitator: `Abre ${title} en vivo y explica solo esta superficie antes de pasar a la siguiente.`,
        audienceNotes: {
          customer: `Enmarca ${title} como una superficie operativa concreta, no solo como un label del menu.`,
          partner: `Enmarca ${title} como parte de un walkthrough repetible que el partner puede reutilizar con clientes.`,
        },
        ...override?.es,
      },
      pt: {
        summary: slug === 'integrations'
          ? 'Conecte servicos externos para estender o Seal.'
          : slug === 'mcp-servers'
            ? 'Servidores MCP remotos disponiveis para todos os seus workspaces.'
            : pt.description,
        purpose: pt.purpose,
        howToUse: pt.howToUse,
        benefit: pt.benefit,
        prompt: `Explique ${title} no Cloudflare OS: por que existe, como devo usa-lo e que beneficio ele me traz.`,
        facilitator: `Abra ${title} ao vivo e explique apenas esta superficie antes de passar para a proxima.`,
        audienceNotes: {
          customer: `Enquadre ${title} como uma superficie operacional concreta, e nao apenas como um label de menu.`,
          partner: `Enquadre ${title} como parte de um walkthrough repetivel que o parceiro pode reutilizar com clientes.`,
        },
        ...override?.pt,
      },
    },
  });
}

