function buildExercise(enSummary, esSummary, ptSummary, sources) {
  return {
    sources,
    content: {
      en: { summary: enSummary, objective: 'Apply Cloudflare OS to a real enablement or customer-delivery task.', steps: ['Review the scenario and choose the safest demo path.', 'Run the exercise inside Cloudflare OS with the right sources.', 'Capture the output and next action.'], outputs: ['Finished exercise output', 'Risk notes', 'Follow-up action'], reference: ['Start with a customer-safe path before using live systems.', 'State the data sources, trust boundary, and desired artifact before you begin.', 'End each exercise with one output and one concrete next action.'], prompt: `Guide me through the exercise: ${enSummary} Produce a practical output and list the next action.`, facilitator: 'Use exercises to prove value with a concrete outcome, not just to showcase product surface area.' },
      es: { summary: esSummary, objective: 'Aplicar Cloudflare OS a una tarea real de enablement o delivery con cliente.', steps: ['Revisa el escenario y elige la ruta demo más segura.', 'Ejecuta el ejercicio dentro de Cloudflare OS con las fuentes correctas.', 'Captura el output y la siguiente acción.'], outputs: ['Output terminado del ejercicio', 'Notas de riesgo', 'Siguiente acción'], reference: ['Empieza con una ruta customer-safe antes de usar sistemas en vivo.', 'Declara las fuentes de datos, el límite de confianza y el artefacto deseado antes de comenzar.', 'Cierra cada ejercicio con un output y una siguiente acción concreta.'], prompt: `Guíame en el ejercicio: ${esSummary} Produce un output práctico y lista la siguiente acción.`, facilitator: 'Usa ejercicios para probar valor con un resultado concreto, no solo para enseñar superficie de producto.' },
      pt: { summary: ptSummary, objective: 'Aplicar Cloudflare OS a uma tarefa real de enablement ou entrega ao cliente.', steps: ['Revise o cenário e escolha o caminho demo mais seguro.', 'Execute o exercício dentro do Cloudflare OS com as fontes corretas.', 'Capture o output e a próxima ação.'], outputs: ['Output final do exercício', 'Notas de risco', 'Próxima ação'], reference: ['Comece com um caminho customer-safe antes de usar sistemas ao vivo.', 'Declare as fontes de dados, o limite de confiança e o artefato desejado antes de começar.', 'Feche cada exercício com um output e uma próxima ação concreta.'], prompt: `Guie-me no exercício: ${ptSummary} Produza um output prático e liste a próxima ação.`, facilitator: 'Use exercícios para provar valor com um resultado concreto, não apenas para mostrar superfície de produto.' },
    },
  };
}

